from pathlib import Path
from playwright.sync_api import sync_playwright
import subprocess, tempfile, shutil, os
root=Path(__file__).resolve().parents[3]
tmp=tempfile.TemporaryDirectory();pdir=Path(tmp.name)
subprocess.run(['tsc','--target','ES2022','--module','ESNext','--moduleResolution','bundler','--lib','ES2022,DOM,DOM.Iterable','--strict','--outDir',str(pdir),'src/ui/menus.ts'],cwd=root,check=True)
shutil.copy(root/'src/ui/menus.css',pdir/'menus.css')
shutil.copy(Path(__file__).with_name('fixture.js'),pdir/'fixture.js')
preview=Path(os.environ.get('PB_MENU_PREVIEW',str(pdir)));preview.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or shutil.which('chromium'),args=['--no-sandbox']); page=b.new_page(viewport={'width':1600,'height':1000}); errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content('<meta charset="utf-8"><style>body{margin:0;background:#0b1c25}#root{min-height:100vh}'+(pdir/'menus.css').read_text()+'</style><div id="root"></div>')
 source=(pdir/'ui/menus.js').read_text();source='\n'.join(l for l in source.splitlines() if not l.startswith('import ')).replace('export function','function');fixture=(pdir/'fixture.js').read_text().split('\n',1)[1]
 page.add_script_tag(content=source+'\n'+fixture); page.locator('[data-focus=campaign]').wait_for(); page.screenshot(path=str(preview/'64-title.png'),animations='disabled');page.locator('[data-focus=campaign]').click();assert page.locator('.pb-map').count()==20;page.locator('[data-focus=difficulty-hard]').click();page.locator('[data-focus=map-map20]').click();assert page.locator('[data-focus=difficulty-hard]').get_attribute('aria-pressed')=='true';assert page.locator('[data-focus=start]').is_disabled();assert 'Сначала пройди' in page.locator('.pb-warning').inner_text();page.locator('[data-focus=map-map1]').click();assert page.locator('[data-focus=start]').is_enabled();assert page.locator('option[value=half-cash]').is_disabled();page.locator('.pb-menu').evaluate('(e)=>e.scrollTop=0');page.screenshot(path=str(preview/'64-campaign.png'),animations='disabled');page.locator('[data-focus=back]').click();page.locator('[data-focus=campaign]').click();assert page.locator('[data-focus=difficulty-hard]').get_attribute('aria-pressed')=='true';page.locator('[data-focus=start]').focus();page.keyboard.press('Enter');assert page.evaluate('fixture.calls.filter(x=>x[0]==="start").length')==1;page.evaluate('fixture.show("maps")');assert page.locator('[data-focus=start]').is_disabled();page.evaluate('fixture.ui.hide();fixture.profile.completedNodes.push("n1");fixture.profile.unlockedTowers.push("scatter","ember");fixture.show("maps")');page.locator('[data-focus=mode]').select_option('no-leaks');assert page.locator('.pb-metrics').inner_text().splitlines()[3]=='1';assert '80' in page.locator('.pb-metrics').inner_text();page.evaluate('fixture.show("victory",fixture.run,fixture.receipt)');assert 'Первая медаль' in page.locator('.pb-result').inner_text();assert 'Новые технологии' in page.locator('.pb-result').inner_text();page.screenshot(path=str(preview/'64-victory.png'),animations='disabled');page.evaluate('fixture.show("victory",fixture.run,{...fixture.receipt,firstClear:false})');assert 'Повторная медаль' in page.locator('.pb-result').inner_text();page.evaluate('fixture.show("victory",fixture.run,{...fixture.receipt,duplicate:true})');assert 'Повторного начисления нет' in page.locator('.pb-result').inner_text();assert '+500' not in page.locator('.pb-result').inner_text();page.evaluate('fixture.show("victory",fixture.run)');assert 'Подтверждённой награды нет' in page.locator('.pb-result').inner_text();page.evaluate('fixture.show("settings")');page.locator('[data-focus=reducedMotion]').check();assert page.locator('.pb-menu').get_attribute('data-motion')=='false';page.locator('[data-focus=language]').select_option('en');assert 'Settings' in page.locator('h1').inner_text();page.evaluate('fixture.show("title")');page.locator('[data-focus=coop]').click();page.locator('[data-focus=knowledge]').click();assert page.evaluate('fixture.calls.some(x=>x[0]==="coop") && fixture.calls.some(x=>x[0]==="knowledge")');page.evaluate('fixture.ui.dispose()');assert page.locator('.pb-menu').count()==0;assert not errors,errors;print('Chromium: all assertions passed');b.close()
